# d10gens.py q: finds D10 (order 20, dihedral) inside PGL(2,q) generated by c (order 10) and a reflection t.
# Prints "a b c d" matrices (entries mod q, normalised so the first nonzero entry is 1 for PGL elements).
import sys, random
q = int(sys.argv[1]) if len(sys.argv) > 1 else 229
random.seed(int(sys.argv[2]) if len(sys.argv) > 2 else 5)
def mul(x, y): return ((x[0]*y[0]+x[1]*y[2]) % q, (x[0]*y[1]+x[1]*y[3]) % q, (x[2]*y[0]+x[3]*y[2]) % q, (x[2]*y[1]+x[3]*y[3]) % q)
def pn(x):
    # projective normal form: scale so the first nonzero entry equals 1
    for v in x:
        if v:
            iv = pow(v, q-2, q); return tuple((w*iv) % q for w in x)
    return x
I = (1, 0, 0, 1)
def order(x):
    y = pn(x); k = 1
    while y != I:
        y = pn(mul(y, x)); k += 1
        if k > 1000: return -1
    return k
def inv(x): return (x[3], (-x[1]) % q, (-x[2]) % q, x[0])
def closure(gens, cap=100):
    S = {I}; fr = [I]
    while fr:
        nf = []
        for x in fr:
            for g in gens:
                y = pn(mul(x, g))
                if y not in S:
                    S.add(y); nf.append(y)
                    if len(S) > cap: return S
        fr = nf
    return S
# order-10 element: random matrix with trace^2/det not in a split torus, pick one whose order is 10
c = None
while c is None:
    a, b, cc, d = (random.randrange(q) for _ in range(4))
    if (a*d - b*cc) % q == 0: continue
    x = pn((a, b, cc, d))
    if order(x) == 10: c = x
# reflection t: involution with t c t^-1 = c^-1 (in PGL): search random involutions and test
t = None
tries = 0
while t is None:
    tries += 1
    a, b, cc = (random.randrange(q) for _ in range(3))
    if a == 0 and cc == 0: continue
    # involutions in PGL: trace 0 matrices (a, b, c, -a) with det != 0
    if cc: x = (a, b, cc, (-a) % q)
    else: x = (a, b, 0, (-a) % q)
    det = (x[0]*x[3] - x[1]*x[2]) % q
    if det == 0: continue
    x = pn(x)
    if order(x) != 2: continue
    lhs = pn(mul(mul(x, c), x))
    if lhs == pn(inv(c)):
        t = x
L = closure([c, t])
print("order_L", len(L), "order_c", order(c), "order_t", order(t), file=sys.stderr)
print("c", " ".join(map(str, c)))
print("t", " ".join(map(str, t)))
